function requiredValue(name: string): unknown {
  switch (name) {
    case 'ariaLabel':
      return 'Test action';
    case 'item':
      return { id: 'navigation-item', label: 'Home', href: '#' };
    case 'fileData':
      return {
        id: 'test-file',
        name: 'document.txt',
        type: 'text/plain',
        size: 4,
        file: new File(['test'], 'document.txt'),
        progress: 0,
        status: 'pending',
      };
    case 'toast':
      return {
        id: 'test-toast',
        type: 'info',
        title: 'Notification',
        message: 'Message',
        duration: 0,
        dismissible: true,
        showIcon: true,
        position: 'top-right',
        pauseOnHover: true,
        createdAt: 0,
      };
    default:
      throw new Error('Add a meaningful fixture for required input ' + name);
  }
}

describe('Every component: rendering, instance isolation and teardown', () => {
  for (const entry of components) {
    it(entry.name, () => {
      TestBed.configureTestingModule({ providers: [provideRouter([])] });
      const fixtures = [
        TestBed.createComponent(entry.type),
        TestBed.createComponent(entry.type),
      ];
      for (const fixture of fixtures) {
        for (const name of entry.required)
          fixture.componentRef.setInput(name, requiredValue(name));
        fixture.detectChanges();
      }
      const ids = fixtures
        .flatMap((fixture) =>
          Array.from(
            (fixture.nativeElement as HTMLElement).querySelectorAll('[id]'),
          ).map((element) => element.id),
        )
        .filter(Boolean);
      expect(new Set(ids).size)
        .withContext('Rendered IDs must be unique within and across instances')
        .toBe(ids.length);
      for (const fixture of fixtures)
        expect(() => fixture.destroy()).not.toThrow();
    });
  }
});
